#[derive(Clone, Copy)]
struct Artifact {
    path: &'static str,
    role: &'static str,
    grain: &'static str,
    kind: &'static str,
    canonical: &'static str,
}

impl Artifact {
    fn metadata(&self) -> ArtifactMetadata<'_> {
        ArtifactMetadata {
            path: self.path,
            role: self.role,
            grain: self.grain,
            kind: self.kind,
            canonical: self.canonical,
        }
    }
}

