fn validate_solver_input_readiness_rollup(root: &Path) -> Result<(), String> {
    for path in [
        SOLVER_INPUT_READINESS_ROLLUP_JSON_PATH,
        SOLVER_INPUT_READINESS_ROLLUP_SCHEMA_PATH,
        SOLVER_INPUT_READINESS_ROLLUP_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!("missing solver input readiness artifact: {path}"));
        }
    }

    let text = fs::read_to_string(root.join(SOLVER_INPUT_READINESS_ROLLUP_JSON_PATH))
        .map_err(|e| e.to_string())?;
    let rollup: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&rollup, "record_id")? != "solver-input-readiness-rollup:v1"
        || string_field(&rollup, "record_family")? != "solver_input_readiness_rollup"
        || int_field(&rollup, "pulse")? != 107
        || string_field(&rollup, "solver_input_inventory_path")? != SOLVER_INPUT_INVENTORY_JSON_PATH
        || string_field(&rollup, "reserve_rule_contract_path")? != RESERVE_RULE_CONTRACT_JSON_PATH
        || string_field(&rollup, "reserve_parameter_readiness_gate_path")?
            != RESERVE_PARAMETER_READINESS_GATE_JSON_PATH
        || string_field(&rollup, "net_interest_formula_contract_path")?
            != NET_INTEREST_FORMULA_CONTRACT_JSON_PATH
        || string_field(&rollup, "assigned_receipt_base_inventory_path")?
            != ASSIGNED_RECEIPT_BASE_INVENTORY_JSON_PATH
        || string_field(&rollup, "distributional_effect_placeholder_path")?
            != DISTRIBUTIONAL_EFFECT_PLACEHOLDER_JSON_PATH
    {
        return Err("solver input readiness rollup identity failed".to_string());
    }

    let rows = rollup
        .get("rollup_rows")
        .and_then(serde_json::Value::as_array)
        .ok_or("solver input readiness rows")?;
    let observed = rows
        .iter()
        .map(|row| string_field(row, "input_id"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected = [
        "full_17_row_fy2025_ledger",
        "baseline_plus_ten_year_horizon",
        "oasdi_fund_path",
        "medicare_hi_fund_path",
        "transportation_trust_fund_path",
        "general_fund_path",
        "reserves_path",
        "explicit_interfund_transfers",
        "credited_offsetting_collections",
        "net_interest_formula",
        "assigned_receipt_bases",
        "distributional_effect_placeholder",
    ]
    .into_iter()
    .map(str::to_string)
    .collect::<BTreeSet<_>>();
    if observed != expected || rows.len() != expected.len() {
        return Err("solver input readiness row set failed".to_string());
    }

    let rows_by_id = rows
        .iter()
        .map(|row| Ok((string_field(row, "input_id")?, row)))
        .collect::<Result<BTreeMap<_, _>, String>>()?;
    for row in rows {
        if row.get("ready").and_then(serde_json::Value::as_bool) != Some(false)
            || !row.get("value").is_some_and(serde_json::Value::is_null)
        {
            return Err("solver input readiness rows must remain false/null".to_string());
        }
        let blockers = row
            .get("remaining_blockers")
            .and_then(serde_json::Value::as_array)
            .ok_or("solver input readiness blockers")?;
        if blockers.is_empty() {
            return Err("solver input readiness rows must name blockers".to_string());
        }
    }
    for (input_id, path, status) in [
        (
            "reserves_path",
            RESERVE_PARAMETER_READINESS_GATE_JSON_PATH,
            "contract_and_parameter_gate_only",
        ),
        (
            "net_interest_formula",
            NET_INTEREST_FORMULA_CONTRACT_JSON_PATH,
            "formula_contract_only_inputs_missing",
        ),
        (
            "assigned_receipt_bases",
            ASSIGNED_RECEIPT_BASE_INVENTORY_JSON_PATH,
            "inventory_only_amounts_behavior_distribution_missing",
        ),
        (
            "distributional_effect_placeholder",
            DISTRIBUTIONAL_EFFECT_PLACEHOLDER_JSON_PATH,
            "placeholder_only_distribution_values_missing",
        ),
    ] {
        let row = rows_by_id
            .get(input_id)
            .ok_or("solver input readiness linked row")?;
        if string_field(row, "current_artifact_path")? != path
            || string_field(row, "rollup_status")? != status
        {
            return Err(format!(
                "solver input readiness linked row failed {input_id}"
            ));
        }
    }

    let aggregate = rollup
        .get("aggregate_status")
        .and_then(serde_json::Value::as_object)
        .ok_or("solver input readiness aggregate status")?;
    for (field, value) in aggregate {
        let observed = value
            .as_bool()
            .ok_or("solver input readiness aggregate bool")?;
        if field == "current_cost_reconciled" {
            if !observed {
                return Err("current_cost_reconciled must remain true".to_string());
            }
        } else if observed {
            return Err(format!(
                "solver input readiness aggregate {field} must be false"
            ));
        }
    }

    let claims = rollup
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("solver input readiness claims")?;
    for (field, value) in claims {
        let observed = value.as_bool().ok_or("solver input readiness claim bool")?;
        if field == "solver_input_readiness_rollup_published" {
            if !observed {
                return Err("solver input readiness publish flag must be true".to_string());
            }
        } else if observed {
            return Err(format!(
                "solver input readiness public claim {field} must be false"
            ));
        }
    }

    let boundary = string_field(&rollup, "non_claim_boundary")?;
    for required in [
        "solver-input readiness rollup",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a public rate card",
        "not a tax proposal",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !boundary.contains(required) {
            return Err(format!(
                "solver input readiness boundary missing {required}"
            ));
        }
    }

    let reader = fs::read_to_string(root.join(SOLVER_INPUT_READINESS_ROLLUP_READER_PATH))
        .map_err(|e| e.to_string())?;
    for required in [
        SOLVER_INPUT_READINESS_ROLLUP_JSON_PATH,
        "does not make the solver ready",
        "Every solver input remains not ready and null",
        "reserves path: contract and parameter gate only",
        "net interest formula: formula contract only",
        "assigned receipt bases: inventory only",
        "distributional effect placeholder: placeholder only",
        "OASDI annual fund path",
        "Medicare HI annual fund path",
        "transportation trust-fund annual values",
        "explicit deficit gap",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(required) {
            return Err(format!("solver input readiness reader missing {required}"));
        }
    }

    Ok(())
}

fn validate_current_law_path_inventory(root: &Path) -> Result<(), String> {
    for path in [
        CURRENT_LAW_PATH_INVENTORY_JSON_PATH,
        CURRENT_LAW_PATH_INVENTORY_SCHEMA_PATH,
        CURRENT_LAW_PATH_INVENTORY_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!(
                "missing current-law path inventory artifact: {path}"
            ));
        }
    }

    let text = fs::read_to_string(root.join(CURRENT_LAW_PATH_INVENTORY_JSON_PATH))
        .map_err(|e| e.to_string())?;
    let inventory: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&inventory, "record_id")? != "current-law-path-inventory:v1"
        || string_field(&inventory, "record_family")? != "current_law_path_inventory"
        || int_field(&inventory, "pulse")? != 108
        || string_field(&inventory, "solver_input_inventory_path")?
            != SOLVER_INPUT_INVENTORY_JSON_PATH
        || string_field(&inventory, "solver_input_readiness_rollup_path")?
            != SOLVER_INPUT_READINESS_ROLLUP_JSON_PATH
        || string_field(&inventory, "program_lane_target_cost_contract_path")?
            != PROGRAM_LANE_TARGET_COST_CONTRACT_JSON_PATH
    {
        return Err("current-law path inventory identity failed".to_string());
    }

    let horizon = inventory
        .get("horizon_requirement")
        .ok_or("current-law horizon requirement")?;
    if int_field(horizon, "baseline_year")? != 2025
        || int_field(horizon, "required_forward_years")? != 10
        || horizon
            .get("interpolation_allowed")
            .and_then(serde_json::Value::as_bool)
            != Some(false)
        || horizon
            .get("missing_values_remain_null")
            .and_then(serde_json::Value::as_bool)
            != Some(true)
    {
        return Err("current-law horizon requirement failed".to_string());
    }
    let required_years = horizon
        .get("required_years")
        .and_then(serde_json::Value::as_array)
        .ok_or("current-law required years")?
        .iter()
        .map(|value| value.as_i64().ok_or("current-law required year int"))
        .collect::<Result<Vec<_>, _>>()?;
    if required_years != (2025..=2035).map(i64::from).collect::<Vec<_>>() {
        return Err("current-law required years must be FY2025-FY2035".to_string());
    }

    let rows = inventory
        .get("path_rows")
        .and_then(serde_json::Value::as_array)
        .ok_or("current-law path rows")?;
    let observed = rows
        .iter()
        .map(|row| string_field(row, "path_id"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected = [
        "full_17_row_fy2025_ledger",
        "baseline_plus_ten_year_horizon",
        "oasdi_fund_path",
        "medicare_hi_fund_path",
        "transportation_trust_fund_path",
        "general_fund_path",
        "health_fiscal_current_law_path",
        "net_interest_current_law_path",
    ]
    .into_iter()
    .map(str::to_string)
    .collect::<BTreeSet<_>>();
    if observed != expected || rows.len() != expected.len() {
        return Err("current-law path row set failed".to_string());
    }
    for row in rows {
        if row.get("required").and_then(serde_json::Value::as_bool) != Some(true)
            || row.get("ready").and_then(serde_json::Value::as_bool) != Some(false)
            || !row.get("value").is_some_and(serde_json::Value::is_null)
        {
            return Err("current-law path rows must be required/false/null".to_string());
        }
        let missing_years = row
            .get("missing_years")
            .and_then(serde_json::Value::as_array)
            .ok_or("current-law missing years")?;
        if missing_years.is_empty() {
            return Err("current-law rows must retain missing years".to_string());
        }
        if string_field(row, "official_source_family")?.is_empty() {
            return Err("current-law rows must name official source family".to_string());
        }
    }

    let rows_by_id = rows
        .iter()
        .map(|row| Ok((string_field(row, "path_id")?, row)))
        .collect::<Result<BTreeMap<_, _>, String>>()?;
    for (path_id, status) in [
        ("baseline_plus_ten_year_horizon", "missing_unified_horizon"),
        ("oasdi_fund_path", "missing_official_annual_path"),
        ("medicare_hi_fund_path", "missing_official_annual_path"),
        (
            "transportation_trust_fund_path",
            "accounting_boundary_only_no_annual_values",
        ),
        (
            "health_fiscal_current_law_path",
            "missing_component_annual_path",
        ),
        (
            "net_interest_current_law_path",
            "formula_contract_only_values_missing",
        ),
    ] {
        if string_field(
            rows_by_id
                .get(path_id)
                .ok_or("current-law path row lookup")?,
            "coverage_status",
        )? != status
        {
            return Err(format!("current-law path status failed {path_id}"));
        }
    }

    let rules = inventory
        .get("inventory_rules")
        .and_then(serde_json::Value::as_object)
        .ok_or("current-law rules")?;
    for required in [
        "official_sources_only",
        "raw_bytes_metadata_retrieval_date_byte_count_and_sha256_required",
        "no_interpolation_without_explicit_model",
        "missing_values_remain_null",
        "trust_funds_remain_separate",
        "medicare_hi_must_remain_separate",
        "current_law_zero_reform_delta_required",
    ] {
        if rules.get(required).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!("current-law rule failed {required}"));
        }
    }
    if rules
        .get("solver_ready")
        .and_then(serde_json::Value::as_bool)
        != Some(false)
    {
        return Err("current-law solver_ready must be false".to_string());
    }

    let claims = inventory
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("current-law claims")?;
    for (field, value) in claims {
        let observed = value.as_bool().ok_or("current-law claim bool")?;
        if field == "current_law_path_inventory_published" {
            if !observed {
                return Err("current-law inventory publish flag must be true".to_string());
            }
        } else if observed {
            return Err(format!("current-law public claim {field} must be false"));
        }
    }

    let boundary = string_field(&inventory, "non_claim_boundary")?;
    for required in [
        "current-law path inventory",
        "not current-law path values",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a public rate card",
        "not a tax proposal",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !boundary.contains(required) {
            return Err(format!("current-law boundary missing {required}"));
        }
    }

    let reader = fs::read_to_string(root.join(CURRENT_LAW_PATH_INVENTORY_READER_PATH))
        .map_err(|e| e.to_string())?;
    for required in [
        CURRENT_LAW_PATH_INVENTORY_JSON_PATH,
        "does not publish current-law path values",
        "Required years: FY2025 through FY2035",
        "OASDI annual fund path",
        "Medicare HI annual fund path",
        "transportation trust-fund annual values",
        "health fiscal current-law path",
        "net interest current-law path",
        "raw bytes, metadata, retrieval date, byte count, and SHA-256",
        "Interpolation is not allowed without an explicit model",
        "Missing values remain null",
        "Trust funds remain separate",
        "Medicare HI remains separate",
        "not current-law path values",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(required) {
            return Err(format!("current-law reader missing {required}"));
        }
    }

    Ok(())
}

fn validate_current_law_source_custody_preflight(root: &Path) -> Result<(), String> {
    for path in [
        CURRENT_LAW_SOURCE_CUSTODY_PREFLIGHT_JSON_PATH,
        CURRENT_LAW_SOURCE_CUSTODY_PREFLIGHT_SCHEMA_PATH,
        CURRENT_LAW_SOURCE_CUSTODY_PREFLIGHT_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!(
                "missing current-law source-custody preflight artifact: {path}"
            ));
        }
    }

    let text = fs::read_to_string(root.join(CURRENT_LAW_SOURCE_CUSTODY_PREFLIGHT_JSON_PATH))
        .map_err(|e| e.to_string())?;
    let preflight: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&preflight, "record_id")? != "current-law-source-custody-preflight:v1"
        || string_field(&preflight, "record_family")? != "current_law_source_custody_preflight"
        || int_field(&preflight, "pulse")? != 109
        || string_field(&preflight, "current_law_path_inventory_path")?
            != CURRENT_LAW_PATH_INVENTORY_JSON_PATH
        || string_field(&preflight, "solver_input_readiness_rollup_path")?
            != SOLVER_INPUT_READINESS_ROLLUP_JSON_PATH
        || string_field(&preflight, "program_lane_target_cost_contract_path")?
            != PROGRAM_LANE_TARGET_COST_CONTRACT_JSON_PATH
    {
        return Err("current-law source-custody preflight identity failed".to_string());
    }

    let requirements = preflight
        .get("custody_packet_requirements")
        .and_then(serde_json::Value::as_array)
        .ok_or("current-law source-custody requirements")?
        .iter()
        .map(|value| {
            value
                .as_str()
                .map(str::to_string)
                .ok_or("current-law source-custody requirement string")
        })
        .collect::<Result<Vec<_>, _>>()?;
    if requirements
        != [
            "source_id",
            "official_host_or_publisher",
            "source_vintage",
            "retrieval_date",
            "raw_artifact_path",
            "raw_byte_count",
            "raw_sha256",
            "metadata_path",
            "extraction_method",
            "annual_years_covered",
            "component_mapping",
            "review_status",
        ]
        .into_iter()
        .map(str::to_string)
        .collect::<Vec<_>>()
    {
        return Err("current-law source-custody requirement list changed".to_string());
    }

    let rows = preflight
        .get("preflight_rows")
        .and_then(serde_json::Value::as_array)
        .ok_or("current-law source-custody rows")?;
    let observed = rows
        .iter()
        .map(|row| string_field(row, "path_id"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected = [
        "full_17_row_fy2025_ledger",
        "baseline_plus_ten_year_horizon",
        "oasdi_fund_path",
        "medicare_hi_fund_path",
        "transportation_trust_fund_path",
        "general_fund_path",
        "health_fiscal_current_law_path",
        "net_interest_current_law_path",
    ]
    .into_iter()
    .map(str::to_string)
    .collect::<BTreeSet<_>>();
    if observed != expected || rows.len() != expected.len() {
        return Err("current-law source-custody row set failed".to_string());
    }

    let nullable_fields = [
        "source_id",
        "official_host_or_publisher",
        "source_vintage",
        "retrieval_date",
        "raw_artifact_path",
        "raw_byte_count",
        "raw_sha256",
        "metadata_path",
        "extraction_method",
        "annual_years_covered",
        "component_mapping",
        "review_status",
    ];
    for row in rows {
        if row.get("required").and_then(serde_json::Value::as_bool) != Some(true)
            || row
                .get("custody_ready")
                .and_then(serde_json::Value::as_bool)
                != Some(false)
            || row
                .get("values_may_be_populated")
                .and_then(serde_json::Value::as_bool)
                != Some(false)
        {
            return Err("current-law source-custody rows must be required/false/false".to_string());
        }
        if string_field(row, "candidate_official_source_family")?.is_empty() {
            return Err("current-law source-custody rows must name source family".to_string());
        }
        for field in nullable_fields {
            if !row.get(field).is_some_and(serde_json::Value::is_null) {
                return Err(format!(
                    "current-law source-custody field {field} must remain null"
                ));
            }
        }
        let blockers = row
            .get("remaining_blockers")
            .and_then(serde_json::Value::as_array)
            .ok_or("current-law source-custody blockers")?;
        if blockers.is_empty() {
            return Err("current-law source-custody rows need blockers".to_string());
        }
    }

    let rules = preflight
        .get("preflight_rules")
        .and_then(serde_json::Value::as_object)
        .ok_or("current-law source-custody rules")?;
    for required in [
        "no_external_request_submitted",
        "no_source_values_captured",
        "raw_bytes_required_before_value",
        "metadata_required_before_value",
        "retrieval_date_required_before_value",
        "byte_count_required_before_value",
        "sha256_required_before_value",
        "review_required_before_value",
        "missing_values_remain_null",
    ] {
        if rules.get(required).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!("current-law source-custody rule failed {required}"));
        }
    }
    if rules
        .get("solver_ready")
        .and_then(serde_json::Value::as_bool)
        != Some(false)
    {
        return Err("current-law source-custody solver_ready must be false".to_string());
    }

    let claims = preflight
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("current-law source-custody claims")?;
    for (field, value) in claims {
        let observed = value
            .as_bool()
            .ok_or("current-law source-custody claim bool")?;
        if field == "current_law_source_custody_preflight_published" {
            if !observed {
                return Err("current-law source-custody publish flag must be true".to_string());
            }
        } else if observed {
            return Err(format!(
                "current-law source-custody public claim {field} must be false"
            ));
        }
    }

    let boundary = string_field(&preflight, "non_claim_boundary")?;
    for required in [
        "current-law source-custody preflight",
        "not source custody",
        "not current-law path values",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a public rate card",
        "not a tax proposal",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !boundary.contains(required) {
            return Err(format!(
                "current-law source-custody boundary missing {required}"
            ));
        }
    }

    let reader = fs::read_to_string(root.join(CURRENT_LAW_SOURCE_CUSTODY_PREFLIGHT_READER_PATH))
        .map_err(|e| e.to_string())?;
    for required in [
        CURRENT_LAW_SOURCE_CUSTODY_PREFLIGHT_JSON_PATH,
        "does not publish source custody",
        "does not publish current-law path values",
        "No external request was submitted",
        "No source values were captured",
        "raw bytes",
        "metadata",
        "retrieval date",
        "byte count",
        "SHA-256",
        "review",
        "full 17-row FY2025 ledger",
        "baseline plus ten-year unified horizon",
        "OASDI annual fund path",
        "Medicare HI annual fund path",
        "transportation trust-fund annual values",
        "general fund annual path",
        "health fiscal current-law path",
        "net interest current-law path",
        "not source custody",
        "not current-law path values",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(required) {
            return Err(format!(
                "current-law source-custody reader missing {required}"
            ));
        }
    }

    Ok(())
}

fn validate_lane_depth_explainability_tracker(root: &Path) -> Result<(), String> {
    for path in [
        LANE_DEPTH_EXPLAINABILITY_TRACKER_JSON_PATH,
        LANE_DEPTH_EXPLAINABILITY_TRACKER_SCHEMA_PATH,
        LANE_DEPTH_EXPLAINABILITY_TRACKER_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!(
                "missing lane depth explainability tracker artifact: {path}"
            ));
        }
    }

    let text = fs::read_to_string(root.join(LANE_DEPTH_EXPLAINABILITY_TRACKER_JSON_PATH))
        .map_err(|e| e.to_string())?;
    let tracker: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&tracker, "record_id")? != "lane-depth-explainability-tracker:v1"
        || string_field(&tracker, "record_family")? != "lane_depth_explainability_tracker"
        || int_field(&tracker, "pulse")? != 110
        || string_field(&tracker, "program_lane_target_cost_contract_path")?
            != PROGRAM_LANE_TARGET_COST_CONTRACT_JSON_PATH
        || string_field(&tracker, "international_comparator_target_rubric_path")?
            != INTERNATIONAL_COMPARATOR_TARGET_RUBRIC_JSON_PATH
        || string_field(&tracker, "solver_input_readiness_rollup_path")?
            != SOLVER_INPUT_READINESS_ROLLUP_JSON_PATH
        || string_field(&tracker, "current_law_source_custody_preflight_path")?
            != CURRENT_LAW_SOURCE_CUSTODY_PREFLIGHT_JSON_PATH
    {
        return Err("lane depth explainability tracker identity failed".to_string());
    }

    let completion = tracker
        .get("completion_definition")
        .ok_or("lane depth completion definition")?;
    for field in [
        "lane_depth_complete_requires",
        "public_explainability_complete_requires",
    ] {
        let values = completion
            .get(field)
            .and_then(serde_json::Value::as_array)
            .ok_or("lane depth completion list")?;
        if values.len() < 8 {
            return Err(format!("lane depth completion list too short: {field}"));
        }
    }
    if completion
        .get("missing_values_remain_null")
        .and_then(serde_json::Value::as_bool)
        != Some(true)
        || completion
            .get("blocked_statuses_remain_false")
            .and_then(serde_json::Value::as_bool)
            != Some(true)
    {
        return Err("lane depth completion null/false rules failed".to_string());
    }

    let aggregate = tracker
        .get("aggregate_status")
        .ok_or("lane depth aggregate status")?;
    if int_field(aggregate, "lane_count")? != 15
        || int_field(aggregate, "lanes_depth_complete")? != 0
        || int_field(aggregate, "lanes_public_explainability_complete")? != 0
        || aggregate
            .get("every_lane_defensible_for_public_rates")
            .and_then(serde_json::Value::as_bool)
            != Some(false)
        || aggregate
            .get("solver_ready")
            .and_then(serde_json::Value::as_bool)
            != Some(false)
        || aggregate
            .get("balanced_rate_ready")
            .and_then(serde_json::Value::as_bool)
            != Some(false)
    {
        return Err("lane depth aggregate status must remain incomplete".to_string());
    }

    let rows = tracker
        .get("lane_rows")
        .and_then(serde_json::Value::as_array)
        .ok_or("lane depth rows")?;
    let observed = rows
        .iter()
        .map(|row| string_field(row, "lane_id"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected = [
        "health-medicare",
        "social-security",
        "national-defense",
        "income-security-family",
        "revenue-solvency",
        "net-interest",
        "payment-integrity",
        "veterans",
        "transportation-infrastructure",
        "education-workforce",
        "disaster-resilience",
        "justice-courts-public-safety",
        "science-energy-environment",
        "agriculture",
        "international-affairs",
    ]
    .into_iter()
    .map(str::to_string)
    .collect::<BTreeSet<_>>();
    if observed != expected || rows.len() != expected.len() {
        return Err("lane depth row set failed".to_string());
    }

    for row in rows {
        for field in [
            "public_label",
            "current_law_baseline_status",
            "source_custody_status",
            "policy_scenario_status",
            "outcome_floor_status",
            "modernization_transition_status",
            "public_explainer_status",
            "solver_mapping_status",
            "next_work",
        ] {
            if string_field(row, field)?.is_empty() {
                return Err(format!("lane depth field empty: {field}"));
            }
        }
        if row
            .get("depth_artifact_paths")
            .and_then(serde_json::Value::as_array)
            .is_none()
        {
            return Err("lane depth artifact paths must be an array".to_string());
        }
        if row
            .get("lane_depth_complete")
            .and_then(serde_json::Value::as_bool)
            != Some(false)
            || row
                .get("public_explainability_complete")
                .and_then(serde_json::Value::as_bool)
                != Some(false)
        {
            return Err("lane depth completion booleans must remain false".to_string());
        }
    }

    let questions = tracker
        .get("public_questions_required_for_each_lane")
        .and_then(serde_json::Value::as_array)
        .ok_or("lane depth public questions")?;
    if questions.len() != 8 {
        return Err("lane depth public question count failed".to_string());
    }

    let claims = tracker
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("lane depth claims")?;
    for (field, value) in claims {
        let observed = value.as_bool().ok_or("lane depth claim bool")?;
        if field == "lane_depth_explainability_tracker_published" {
            if !observed {
                return Err("lane depth tracker publish flag must be true".to_string());
            }
        } else if observed {
            return Err(format!("lane depth public claim {field} must be false"));
        }
    }

    let status = string_field(&tracker, "plain_english_status")?;
    for required in [
        "We are not done",
        "Transportation is the deepest pilot",
        "every lane remains blocked",
        "public rates",
        "target costs",
        "solver output",
        "savings claims",
        "waste claims",
        "fraud claims",
        "department-cut instructions",
        "technology-savings claims",
        "balanced-budget claims",
    ] {
        if !status.contains(required) {
            return Err(format!("lane depth status missing {required}"));
        }
    }

    let reader = fs::read_to_string(root.join(LANE_DEPTH_EXPLAINABILITY_TRACKER_READER_PATH))
        .map_err(|e| e.to_string())?;
    for required in [
        LANE_DEPTH_EXPLAINABILITY_TRACKER_JSON_PATH,
        "we are not done filling out the depth of each lane or the public explainability layer",
        "Transportation is the deepest pilot",
        "Every lane still has missing baseline, source-custody, scenario, outcome-floor",
        "What does this lane do?",
        "What are taxpayers paying now?",
        "Who is served or protected?",
        "What outcomes matter before any lower-cost scenario is admissible?",
        "What would count as overspending, underfunding, or only a review-needed signal?",
        "What can technology change, and what transition risks must be paid for?",
        "What evidence is still missing?",
        "What claims are blocked?",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(required) {
            return Err(format!("lane depth reader missing {required}"));
        }
    }

    Ok(())
}

fn validate_lane_agent_work_order_plan(root: &Path) -> Result<(), String> {
    for path in [
        LANE_AGENT_WORK_ORDER_PLAN_JSON_PATH,
        LANE_AGENT_WORK_ORDER_PLAN_SCHEMA_PATH,
        LANE_AGENT_WORK_ORDER_PLAN_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!("missing lane agent work-order artifact: {path}"));
        }
    }

    let text = fs::read_to_string(root.join(LANE_AGENT_WORK_ORDER_PLAN_JSON_PATH))
        .map_err(|e| e.to_string())?;
    let plan: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&plan, "record_id")? != "lane-agent-work-order-plan:v1"
        || string_field(&plan, "record_family")? != "lane_agent_work_order_plan"
        || int_field(&plan, "pulse")? != 111
        || string_field(&plan, "lane_depth_explainability_tracker_path")?
            != LANE_DEPTH_EXPLAINABILITY_TRACKER_JSON_PATH
        || string_field(&plan, "program_lane_target_cost_contract_path")?
            != PROGRAM_LANE_TARGET_COST_CONTRACT_JSON_PATH
        || string_field(&plan, "international_comparator_target_rubric_path")?
            != INTERNATIONAL_COMPARATOR_TARGET_RUBRIC_JSON_PATH
    {
        return Err("lane agent work-order identity failed".to_string());
    }

    let rules = plan
        .get("parallelization_rules")
        .and_then(serde_json::Value::as_object)
        .ok_or("lane agent parallelization rules")?;
    for required_true in [
        "one_lane_per_agent",
        "one_clean_worktree_per_lane",
        "agents_may_not_share_edit_targets",
        "integration_agent_required_after_each_wave",
        "normative_target_choices_require_review",
        "policy_mechanism_design_requires_review",
        "outcome_floor_threshold_choices_require_review",
    ] {
        if rules
            .get(required_true)
            .and_then(serde_json::Value::as_bool)
            != Some(true)
        {
            return Err(format!("lane agent rule must be true: {required_true}"));
        }
    }
    for required_false in ["external_requests_allowed", "public_claims_allowed"] {
        if rules
            .get(required_false)
            .and_then(serde_json::Value::as_bool)
            != Some(false)
        {
            return Err(format!("lane agent rule must be false: {required_false}"));
        }
    }

    let work_order = plan
        .get("standard_agent_work_order")
        .ok_or("lane agent standard work order")?;
    for field in [
        "required_inputs_to_read",
        "required_outputs_per_lane",
        "required_public_questions",
        "required_claim_firewall",
    ] {
        let values = work_order
            .get(field)
            .and_then(serde_json::Value::as_array)
            .ok_or("lane agent work order list")?;
        if values.len() < 6 {
            return Err(format!("lane agent work-order list too short: {field}"));
        }
    }

    let waves = plan
        .get("assignment_waves")
        .and_then(serde_json::Value::as_array)
        .ok_or("lane agent assignment waves")?;
    if waves.len() != 5 {
        return Err("lane agent wave count failed".to_string());
    }
    let mut lane_ids = BTreeSet::new();
    for wave in waves {
        if int_field(wave, "max_parallel_agents")? > 3
            || wave
                .get("integration_required")
                .and_then(serde_json::Value::as_bool)
                != Some(true)
            || string_field(wave, "wave_id")?.is_empty()
            || string_field(wave, "rationale")?.is_empty()
        {
            return Err("lane agent wave rules failed".to_string());
        }
        let lanes = wave
            .get("lane_ids")
            .and_then(serde_json::Value::as_array)
            .ok_or("lane agent wave lanes")?;
        if lanes.len() != 3 {
            return Err("lane agent waves must contain three lanes each".to_string());
        }
        for lane in lanes {
            let lane = lane.as_str().ok_or("lane agent lane id string")?;
            if !lane_ids.insert(lane.to_string()) {
                return Err(format!("lane agent duplicate lane: {lane}"));
            }
        }
    }
    let expected = [
        "health-medicare",
        "social-security",
        "national-defense",
        "income-security-family",
        "revenue-solvency",
        "net-interest",
        "payment-integrity",
        "veterans",
        "transportation-infrastructure",
        "education-workforce",
        "disaster-resilience",
        "justice-courts-public-safety",
        "science-energy-environment",
        "agriculture",
        "international-affairs",
    ]
    .into_iter()
    .map(str::to_string)
    .collect::<BTreeSet<_>>();
    if lane_ids != expected {
        return Err("lane agent assignment must cover all 15 analytical lanes".to_string());
    }

    let integration = plan
        .get("integration_review_checklist")
        .and_then(serde_json::Value::as_array)
        .ok_or("lane agent integration checklist")?
        .iter()
        .map(|value| {
            value
                .as_str()
                .map(str::to_string)
                .ok_or("lane agent integration checklist string")
        })
        .collect::<Result<BTreeSet<_>, _>>()?;
    for required in [
        "all_15_analytical_lanes_present_once",
        "17_budget_rows_not_confused_with_15_analytical_lanes",
        "revenue_solvency_and_payment_integrity_remain_non_additive_overlays",
        "net_interest_remains_endogenous_and_not_directly_cuttable",
        "trust_funds_remain_separate",
        "missing_values_remain_null",
        "blocked_gates_remain_false",
        "technology_changes_are_transition_paths_not_automatic_savings",
        "international_differences_are_not_savings",
        "improper_payment_estimates_do_not_imply_fraud",
        "public_reader_is_plain_language",
        "validator_and_focused_test_added",
    ] {
        if !integration.contains(required) {
            return Err(format!(
                "lane agent integration checklist missing {required}"
            ));
        }
    }

    let claims = plan
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("lane agent claims")?;
    for (field, value) in claims {
        let observed = value.as_bool().ok_or("lane agent claim bool")?;
        if field == "lane_agent_work_order_plan_published" {
            if !observed {
                return Err("lane agent work-order publish flag must be true".to_string());
            }
        } else if observed {
            return Err(format!("lane agent public claim {field} must be false"));
        }
    }

    let status = string_field(&plan, "plain_english_status")?;
    for required in [
        "Agents can scale",
        "one lane each",
        "clean worktrees",
        "integration review",
        "does not execute lane agents",
        "complete lane depth",
        "calculate rates",
        "publish target costs",
        "claim savings",
        "identify waste or fraud",
        "direct department cuts",
        "claim technology savings",
        "claim a balanced budget",
    ] {
        if !status.contains(required) {
            return Err(format!("lane agent status missing {required}"));
        }
    }

    let reader = fs::read_to_string(root.join(LANE_AGENT_WORK_ORDER_PLAN_READER_PATH))
        .map_err(|e| e.to_string())?;
    for required in [
        LANE_AGENT_WORK_ORDER_PLAN_JSON_PATH,
        "one lane per agent",
        "one clean worktree per lane",
        "one integration review after each wave",
        "Health, Social Security, and Defense",
        "Revenue-solvency, Payment-integrity, and Net-interest overlays",
        "all 15 analytical lanes appear once",
        "the 15 analytical lanes are not confused with the 17 budget rows",
        "revenue-solvency and payment-integrity remain non-additive overlays",
        "net interest remains endogenous",
        "trust funds remain separate",
        "missing values remain null",
        "blocked gates remain false",
        "technology changes are transition paths not automatic savings",
        "international differences are not savings",
        "improper-payment estimates do not imply fraud",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(required) {
            return Err(format!("lane agent reader missing {required}"));
        }
    }

    Ok(())
}

fn validate_wave1_public_topline_lane_depth_packets(root: &Path) -> Result<(), String> {
    for path in [
        WAVE1_PUBLIC_TOPLINE_LANE_DEPTH_PACKETS_JSON_PATH,
        WAVE1_PUBLIC_TOPLINE_LANE_DEPTH_PACKETS_SCHEMA_PATH,
        WAVE1_PUBLIC_TOPLINE_LANE_DEPTH_PACKETS_READER_PATH,
    ] {
        if !root.join(path).exists() {
            return Err(format!("missing wave1 lane-depth packet artifact: {path}"));
        }
    }

    let text = fs::read_to_string(root.join(WAVE1_PUBLIC_TOPLINE_LANE_DEPTH_PACKETS_JSON_PATH))
        .map_err(|e| e.to_string())?;
    let wave: serde_json::Value = serde_json::from_str(&text).map_err(|e| e.to_string())?;

    if string_field(&wave, "record_id")? != "wave1-public-topline-lane-depth-packets:v1"
        || string_field(&wave, "record_family")? != "wave1_public_topline_lane_depth_packets"
        || int_field(&wave, "pulse")? != 112
        || string_field(&wave, "lane_agent_work_order_plan_path")?
            != LANE_AGENT_WORK_ORDER_PLAN_JSON_PATH
        || string_field(&wave, "lane_depth_explainability_tracker_path")?
            != LANE_DEPTH_EXPLAINABILITY_TRACKER_JSON_PATH
        || string_field(&wave, "program_lane_target_cost_contract_path")?
            != PROGRAM_LANE_TARGET_COST_CONTRACT_JSON_PATH
    {
        return Err("wave1 lane-depth packet identity failed".to_string());
    }

    let wave_meta = wave.get("wave").ok_or("wave1 metadata")?;
    if string_field(wave_meta, "wave_id")? != "wave_1_public_topline"
        || wave_meta
            .get("integration_review_required")
            .and_then(serde_json::Value::as_bool)
            != Some(true)
        || wave_meta
            .get("lane_depth_complete_after_wave")
            .and_then(serde_json::Value::as_bool)
            != Some(false)
        || wave_meta
            .get("public_explainability_complete_after_wave")
            .and_then(serde_json::Value::as_bool)
            != Some(false)
        || wave_meta
            .get("solver_ready_after_wave")
            .and_then(serde_json::Value::as_bool)
            != Some(false)
    {
        return Err("wave1 metadata must keep completion and solver blocked".to_string());
    }
    let wave_lanes = wave_meta
        .get("lane_ids")
        .and_then(serde_json::Value::as_array)
        .ok_or("wave1 lane ids")?
        .iter()
        .map(|value| {
            value
                .as_str()
                .map(str::to_string)
                .ok_or("wave1 lane id string")
        })
        .collect::<Result<BTreeSet<_>, _>>()?;
    let expected = ["health-medicare", "social-security", "national-defense"]
        .into_iter()
        .map(str::to_string)
        .collect::<BTreeSet<_>>();
    if wave_lanes != expected {
        return Err("wave1 lane id set failed".to_string());
    }

    let packets = wave
        .get("lane_packets")
        .and_then(serde_json::Value::as_array)
        .ok_or("wave1 lane packets")?;
    if packets.len() != 3 {
        return Err("wave1 must contain exactly three lane packets".to_string());
    }
    let observed = packets
        .iter()
        .map(|row| string_field(row, "lane_id"))
        .collect::<Result<BTreeSet<_>, _>>()?;
    if observed != expected {
        return Err("wave1 packet lane set failed".to_string());
    }
    for packet in packets {
        for field in [
            "public_label",
            "what_it_does",
            "who_is_served_or_protected",
            "overspending_underfunding_boundary",
            "technology_transition_boundary",
        ] {
            if string_field(packet, field)?.is_empty() {
                return Err(format!("wave1 packet field empty: {field}"));
            }
        }
        let pay_now = packet
            .get("what_taxpayers_pay_now")
            .ok_or("wave1 taxpayers pay now")?;
        if !pay_now.get("value").is_some_and(serde_json::Value::is_null) {
            return Err("wave1 pay-now value must remain null".to_string());
        }
        let outcomes = packet
            .get("outcomes_that_matter")
            .and_then(serde_json::Value::as_array)
            .ok_or("wave1 outcomes")?;
        if outcomes.is_empty() {
            return Err("wave1 outcomes must be populated".to_string());
        }
        let blockers = packet
            .get("blocked_evidence")
            .and_then(serde_json::Value::as_array)
            .ok_or("wave1 blockers")?;
        if blockers.len() < 5 {
            return Err("wave1 blocker list too short".to_string());
        }
        let claims = packet
            .get("claim_booleans")
            .and_then(serde_json::Value::as_object)
            .ok_or("wave1 lane claims")?;
        for (field, value) in claims {
            let observed = value.as_bool().ok_or("wave1 lane claim bool")?;
            if field == "lane_depth_packet_published" {
                if !observed {
                    return Err("wave1 lane packet publish flag must be true".to_string());
                }
            } else if observed {
                return Err(format!("wave1 lane public claim {field} must be false"));
            }
        }
    }

    let by_lane = packets
        .iter()
        .map(|packet| Ok((string_field(packet, "lane_id")?, packet)))
        .collect::<Result<BTreeMap<_, _>, String>>()?;
    if !string_field(
        by_lane
            .get("health-medicare")
            .ok_or("wave1 health packet")?,
        "strongest_numeric_boundary",
    )?
    .contains("The $149.786 billion result is a mechanical CY2024 private-insurance payer-payment sensitivity")
    {
        return Err("wave1 health warning missing".to_string());
    }
    let social = by_lane
        .get("social-security")
        .ok_or("wave1 social security packet")?
        .get("trust_fund_boundary")
        .ok_or("wave1 social trust fund boundary")?;
    for required in [
        "social_security_kept_separate_from_medicare",
        "oasdi_trust_fund_accounting_remains_separate",
        "general_fund_transfer_requires_explicit_row",
    ] {
        if social.get(required).and_then(serde_json::Value::as_bool) != Some(true) {
            return Err(format!("wave1 social trust rule failed: {required}"));
        }
    }
    if !string_field(
        by_lane
            .get("national-defense")
            .ok_or("wave1 defense packet")?,
        "control_probe_boundary",
    )?
    .contains("Control probes are review queues, not cut lists")
    {
        return Err("wave1 defense control-probe boundary missing".to_string());
    }

    let integration = wave
        .get("integration_review")
        .and_then(serde_json::Value::as_object)
        .ok_or("wave1 integration review")?;
    for required in [
        "all_wave_lanes_present_once",
        "fifteen_analytical_lanes_not_budget_rows",
        "missing_values_remain_null",
        "blocked_gates_remain_false",
        "trust_funds_remain_separate",
        "international_differences_are_not_savings",
        "improper_payment_estimates_do_not_imply_fraud",
        "technology_changes_are_transition_paths_not_automatic_savings",
    ] {
        if integration
            .get(required)
            .and_then(serde_json::Value::as_bool)
            != Some(true)
        {
            return Err(format!("wave1 integration rule failed: {required}"));
        }
    }

    let claims = wave
        .get("claim_booleans")
        .and_then(serde_json::Value::as_object)
        .ok_or("wave1 aggregate claims")?;
    for (field, value) in claims {
        let observed = value.as_bool().ok_or("wave1 aggregate claim bool")?;
        if field == "wave1_public_topline_lane_depth_packets_published" {
            if !observed {
                return Err("wave1 aggregate publish flag must be true".to_string());
            }
        } else if observed {
            return Err(format!(
                "wave1 aggregate public claim {field} must be false"
            ));
        }
    }

    let status = string_field(&wave, "plain_english_status")?;
    for required in [
        "Health and Medicare",
        "Social Security",
        "National defense",
        "do not complete lane depth",
        "calculate rates",
        "publish target costs",
        "claim savings",
        "identify waste or fraud",
        "direct department cuts",
        "claim technology savings",
        "run the solver",
        "claim a balanced budget",
    ] {
        if !status.contains(required) {
            return Err(format!("wave1 status missing {required}"));
        }
    }

    let reader = fs::read_to_string(root.join(WAVE1_PUBLIC_TOPLINE_LANE_DEPTH_PACKETS_READER_PATH))
        .map_err(|e| e.to_string())?;
    for required in [
        WAVE1_PUBLIC_TOPLINE_LANE_DEPTH_PACKETS_JSON_PATH,
        "Wave 1 covers Health and Medicare, Social Security, and National defense",
        "The $149.786 billion result is a mechanical CY2024 private-insurance payer-payment sensitivity",
        "not gross savings",
        "not net savings",
        "not a premium forecast",
        "not a provider revenue forecast",
        "federal budget effect",
        "target for Medicare or Medicaid",
        "Social Security is kept separate from Medicare",
        "OASDI trust-fund accounting remains separate",
        "Missing values remain null",
        "Control probes are review queues, not cut lists",
        "International defense spending differences are not savings",
        "A GDP band is a policy commitment context, not an efficiency frontier",
        "Technology changes require transition costs and mission-continuity review before any savings claim",
        "the 15 analytical lanes separate from the 17 budget rows",
        "technology changes as transition paths not automatic savings",
        "not a solver run",
        "not target-cost selection",
        "not rate calculation",
        "not a savings estimate",
        "not a waste finding",
        "not a fraud finding",
        "not a department-cut instruction",
        "not a technology-savings claim",
        "not a balanced-budget claim",
    ] {
        if !reader.contains(required) {
            return Err(format!("wave1 reader missing {required}"));
        }
    }

    Ok(())
}

